import('./server.mjs').then(async (m) => {
  // valid batch with missing user
  console.log('--- valid batch ---');
  console.log((await m.callTool('users_get_many', {user_ids:['u2','missing']})).content[0].text);

  // request order preserved
  console.log('--- order ---');
  console.log((await m.callTool('users_get_many', {user_ids:['u3','u1','u2']})).content[0].text);

  // unknown tool
  try { await m.callTool('nope', {}); } catch(e){ console.log('--- unknown tool ---'); console.log(e.message); }

  // extra field
  try { await m.callTool('users_get_many', {user_ids:['u1'], extra:1}); } catch(e){ console.log('--- extra field ---'); console.log(e.message); }

  // duplicate ids
  try { await m.callTool('users_get_many', {user_ids:['u1','u1']}); } catch(e){ console.log('--- duplicate ---'); console.log(e.message); }

  // empty array
  try { await m.callTool('users_get_many', {user_ids:[]}); } catch(e){ console.log('--- empty ---'); console.log(e.message); }

  // not an array
  try { await m.callTool('users_get_many', {user_ids:'u1'}); } catch(e){ console.log('--- not array ---'); console.log(e.message); }

  // too many
  try { await m.callTool('users_get_many', {user_ids:['a','b','c','d','e','f']}); } catch(e){ console.log('--- too many ---'); console.log(e.message); }

  // listTools schema
  console.log('--- listTools ---');
  console.log(JSON.stringify(await m.listTools(), null, 2));
});
